mapper.select:
select message_id, receiver, title, content, biz_type, biz_id, instance_id, read_flag, create_time
from pm_flow_message

    and receiver = #{receiver}
    and read_flag = #{readFlag}

order by message_id desc

mapper.update:
update pm_flow_message
set read_flag = '1'

    and message_id = #{messageId}
    and receiver = #{receiver}
